css:
.pks1-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks1-root,.pks1-root *,.pks1-root *::before,.pks1-root *::after{box-sizing:border-box}
.pks1-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks1-root img{display:block;border:0;max-width:none}
.pks1-root [hidden]{display:none!important}
.pks1-root .n1_2007{align-content:stretch;display:flex;height:32px;align-items:center;position:relative;flex-shrink:0;width:100%;border-style:solid;border-color:var(--wa-line, #33363b);border-width:0;border-bottom-width:1px}
.pks1-root .n1_2008{align-content:stretch;display:flex;flex-direction:column;height:32px;align-items:center;justify-content:center;padding-left:10px;padding-right:10px;padding-top:4px;padding-bottom:4px;position:relative;flex-shrink:0;width:150px}
.pks1-root .n1_767{align-content:stretch;display:flex;flex-direction:column;gap:10px;height:22px;align-items:center;justify-content:center;padding-left:13px;padding-right:13px;padding-top:6px;padding-bottom:6px;position:relative;flex-shrink:0;width:78px}
.pks1-root .n1_768{position:absolute;height:22px;left:0;top:0;width:78px}
.pks1-root .x55{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pks1-root .n1_771{align-content:stretch;display:flex;gap:4px;align-items:center;position:relative;flex-shrink:0;width:52px}
.pks1-root .n1_727{display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:10px;height:10px}
.pks1-root .n1_728{position:absolute;border-radius:9.88px;inset:0.79% 0.78% 0.78% 0.78%;box-shadow:0.988px 1.482px 3.952px 0px rgba(17,168,253,0.2),-0.988px -1.482px 3.952px 0px #094465;background-image:linear-gradient(-41.794772459968044deg, var(--wa-point, rgb(17, 168, 253)) 14.045%, var(--wa-point, rgb(0, 129, 201)) 85.291%)}
.pks1-root .n1_729{position:absolute;inset:0;border-radius:9.88px;filter:blur(0.049px);background-image:linear-gradient(-39.34050551265122deg, var(--wa-point, rgb(17, 168, 253)) 14.752%, var(--wa-point, rgb(0, 129, 201)) 84.809%)}
.pks1-root .n1_730{position:absolute;inset:3.13% 3.13% 3.12% 3.12%;border-radius:9.88px;border-style:solid;border-color:var(--wa-point, #058dd9);border-width:0.099px;background-image:linear-gradient(-39.340502119330154deg, var(--wa-point, rgb(0, 94, 163)) 14.752%, var(--wa-point, rgb(17, 168, 253)) 84.809%)}
.pks1-root .n1_731{position:absolute;inset:3.13% 3.13% 3.12% 3.12%;border-radius:9.88px;filter:blur(0.049px);background-image:linear-gradient(-39.340502119330154deg, var(--wa-point, rgb(0, 94, 163)) 14.752%, var(--wa-point, rgb(17, 168, 253)) 84.809%)}
.pks1-root .n1_773{align-content:stretch;display:flex;align-items:center;justify-content:center;position:relative;flex-shrink:0;width:38px}
.pks1-root .n1_774{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;display:flex;flex:1 0 0;flex-direction:column;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:400;justify-content:center;line-height:0;min-width:1px;font-style:normal;position:relative;font-size:10px;text-align:center;color:var(--wa-text, #fff)}
.pks1-root .n1_774>p:first-of-type:last-of-type,.pks1-root .n1_774>span:first-of-type:last-of-type{text-box-trim:trim-both;text-box-edge:cap alphabetic}
.pks1-root .x56{line-height:1}
.pks1-root .n1_2010{align-content:stretch;display:flex;align-items:center;justify-content:center;overflow:clip;padding-left:10px;padding-right:10px;padding-top:12px;padding-bottom:12px;position:relative;flex-shrink:0;width:223px}
.pks1-root .n1_2011{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:1;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #c1c1c1);font-size:12px;white-space:nowrap;width:96px;height:8px}
.pks1-root .n1_2012{align-content:stretch;display:flex;align-items:center;justify-content:center;padding-left:10px;padding-right:10px;padding-top:12px;padding-bottom:12px;position:relative;flex-shrink:0;width:245px}
