.pks1-root .n1_2014{align-content:stretch;display:flex;align-items:center;justify-content:center;padding-left:10px;padding-right:10px;padding-top:12px;padding-bottom:12px;position:relative;flex-shrink:0;width:232px}
.pks1-root .n1_2015{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:1;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #c1c1c1);font-size:12px;white-space:nowrap;width:112px;height:8px}
.pks1-root .n1_2016{align-content:stretch;display:flex;align-items:center;padding-left:63px;padding-right:10px;padding-top:12px;padding-bottom:12px;position:relative;flex-shrink:0;width:905px}
.pks1-root .n1_2017{text-box-edge:cap alphabetic;text-box-trim:trim-both;word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:500;line-height:1;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-text-sub, #c1c1c1);font-size:12px;white-space:nowrap;width:76px;height:8px}
.pks1-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pks1-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pks1-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pks1-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pks1-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pks1-root[data-theme="light"] .n1_2007{border-color:var(--wa-line, #cfd1d5)}
.pks1-root[data-theme="light"] .n1_774{color:var(--wa-text, #10231d)}
.pks1-root[data-theme="light"] .n1_2011{color:var(--wa-text-sub, #404349)}
.pks1-root[data-theme="light"] .n1_2013{color:var(--wa-text-sub, #404349)}
.pks1-root[data-theme="light"] .n1_2015{color:var(--wa-text-sub, #404349)}
.pks1-root[data-theme="light"] .n1_2017{color:var(--wa-text-sub, #404349)}
